# forge_engineimport streamlit as stimport reimport jsonfrom datetime import datetimedef run_forge_workflow(PATHS, load_json_registry, get_next_available_id):    """    Forge Engine: Handles the creation of new Logic RFC Metric Manifests.    """    st.title("Logic Map Files")    st.header("Forge New Metric")        # Load reference data    sections = load_json_registry("ISIC_Industry_Section_Codes.json") or [{"Industry Sector Name": "General", "ISIC Section": "Z"}]    divisions = load_json_registry("ISIC_Industry_Division_Codes.json") or []    pcf_cats = load_json_registry("PCF_Categories.json") or [{"PCF Category": "Generic", "PCF Code": "0.0"}]        # Header Inputs    col_name, col_id = st.columns([3, 1])    with col_name:         logic_map_name = st.text_input("Metric Name (Logic Label)")    with col_id:         unique_id = st.text_input("ID", value=str(get_next_available_id(PATHS)))    # Classification Logic    section = st.selectbox("Industry Section", sections, format_func=lambda x: x.get("Industry Sector Name"))    sec_letter = section.get("ISIC Section", "Z")        filtered_divs = [d for d in divisions if d.get("ISIC Section") == sec_letter] or [{"Industry Sector / Activity Name": "Default", "ISIC Division": "00"}]    division = st.selectbox("Industry Division", filtered_divs, format_func=lambda x: x.get("Industry Sector / Activity Name"))    pcf = st.selectbox("PCF Category", pcf_cats, format_func=lambda x: x.get("PCF Category"))        # ID Generation Assembly    pcf_code = str(pcf.get('PCF Code')).split('.')[-1].zfill(2)    div_code = re.sub(r'\D', '', str(division.get('ISIC Division')))[-3:].zfill(3)    full_itw_id = f"ITW-{unique_id}.{pcf_code}-{sec_letter}.{div_code}.REF.001"        st.info(f"**Target ITW_ID:** `{full_itw_id}`")    c1, c2, _ = st.columns([3, 3, 2])    with c1:        if st.button("Generate Logic Set"):            man_content = {                "itw_id": full_itw_id,                 "metric_name": logic_map_name,                 "version": "001",                "last_updated": datetime.now().strftime("%Y-%m-%d %H:%M:%S")            }            file_path = PATHS["spec"] / f"MAN_{full_itw_id}.json"            with open(file_path, "w", encoding="utf-8") as f:                json.dump(man_content, f, indent=4)                        st.session_state.last_path = str(file_path)            st.session_state.set_created = True            st.success(f"Generated {file_path.name}")                with c2:        if st.session_state.get('set_created', False):            if st.button("Discard/Undo"):                import os                if os.path.exists(st.session_state.last_path):                     os.remove(st.session_state.last_path)                st.session_state.set_created = False                st.rerun()